(async()=>{const out={};for(const [frequency,detune]of [[0,153600],[440,153600],[440,-153600],[0,-153600]]){const c=new OfflineAudioContext(1,8,48000),o=new OscillatorNode(c,{frequency,detune});o.connect(c.destination);o.start();out[frequency+','+detune]=Array.from((await c.startRendering()).getChannelData(0));}const c=new OfflineAudioContext(1,8,48000),o=c.createOscillator();o.frequency.setValueAtTime(100000,0);o.detune.setValueAtTime(-1200,0);o.connect(c.destination);o.start();out.automatedBounds=Array.from((await c.startRendering()).getChannelData(0));return out})()
